import csv
import re

data = """"Isla de las Muñecas (Bebekler Adası)","Meksiko (Xochimilco)","Meksika","Yüzlerce çürüyen oyuncak bebeğin ağaçlardan sallandığı, kanalların ortasındaki bu kabus adası. Boğularak ölen küçük bir kızın arafta kalan ruhunu yatıştırmak için asılan bu bebeklerin boş gözleri sizi izler; adanın o karanlık, bataklık enerjisi ve bebeklerin içine hapsolmuş alt boyut varlıkları auranızı anında kilitler.",5"Posada del Sol Oteli","Meksiko","Meksika","Mimarı Fernando Saldaña'nın inşaat sırasında otelin çan kulesinde kendini asarak intihar ettiği bu devasa, lanetli harabe. Masonik sembollerle dolu labirent gibi koridorlarında dolaşırken, karanlık ritüellerin ve arafta kalan küçük bir kız çocuğunun (Oda 103) o ezici, melankolik frekansı göğsünüze kurşun gibi oturur.",5"Panteón de Belén","Guadalajara","Meksika","Gotik mimarisi ve vampir efsaneleriyle ünlü bu 19. yüzyıl mezarlığı. Gece çöktüğünde devasa mermer anıtların arasından süzülen şekilsiz kütleler ve toprağın altından nabız gibi atan o aristokratik ölüm frekansı, burayı okültistlerin ve yeraltı varlıklarının aktif bir toplanma alanına çevirir.",4"Real de Catorce (Hayalet Kasaba)","San Luis Potosí","Meksika","Çölün ortasında, Ogarrio Tüneli'nin ardına gizlenmiş ve gümüş madenlerinin tükenmesiyle bir gecede terk edilmiş bu hayalet kasaba. Karanlık ve devasa maden dehlizlerinde yankılanan 'El Jergas' (hayalet madenci) adımları ve toprağın o aç, yutucu enerjisi, zamanın burada tamamen durduğunu ruhunuza fısıldar.",4"San Juan de Ulúa Kalesi","Veracruz","Meksika","İspanyol sömürge döneminin en kanlı hapishanelerinden ve işkence merkezlerinden biri olan bu deniz kalesi. Suya gömülü zindanlarında (tinajas) hastalık ve işkenceyle can veren binlerce mahkumun o paslı çaresizliği taşlara kan gibi işlemiştir; dalga seslerine karışan bedensiz feryatlar aklınızı zorlar.",5"Casa de los Tubos (Borular Evi)","Monterrey","Meksika","Tekerlekli sandalyeye mahkum kızının intiharı (veya cinayeti) sonrası inşaatı yarım kalan, tuhaf silindirik mimarisiyle bilinen bu lanetli yapı. Binanın merkezine doğru çekildiğinizi hissettiren o girdap (vortex) enerjisi ve geceleri duyulan o çaresiz kız çocuğu ağlamaları, buradaki boyut perdesinin tamamen yırtıldığını gösterir.",4"Callejón del Aguacate (Avokado Sokağı)","Meksiko (Coyoacán)","Meksika","Gündüzleri huzurlu görünen ama karanlık çöktüğünde kara büyü (brujería) ve voodoo ritüellerinin merkezine dönüşen bu dar İspanyol sokağı. Ağaçta asılarak katledilen küçük bir çocuğun hıçkırıklarının duvarlarda yankılandığı ve aniden cihazların pillerini emen o aç, şeytani frekans ziyaretçilerin aurasını bıçaklar.",4"Hospital Juárez","Meksiko","Meksika","'La Planchada' (Ütülü Hemşire) efsanesinin doğduğu, depremlerde ve salgınlarda on binlerce insanın acı içinde can verdiği bu asırlık hastane. Eski koğuşların o ağır, ilaç kokulu ölüm frekansı ve geceleri koridorlarda dolaşan bedensiz personelin adımları, burayı hastalıklı bir astral araf haline getirmiştir.",4"Cueva del Diablo (Şeytan Mağarası)","Mazatlán","Meksika","Pasifik okyanusunun kıyısında, efsaneye göre doğrudan Lucifer ile anlaşmaların yapıldığı ve korsanların kanlı ritüeller düzenlediği bu zifiri karanlık mağara. Sülfür kokusunun okyanus iyoduna karıştığı bu derin çukurda durduğunuzda, alt boyut varlıklarının fısıltıları ve o hipnotik karanlığın auranızı emdiğini fiziksel olarak hissedersiniz.",5"Hacienda de Cholul","Mérida","Meksika","Sahiplerinin büyücülük ve vahşi cinayetlerle birbirini katlettiği, ormanın yuttuğu bu terk edilmiş devasa kauçuk malikanesi. Yıkık dökük taş duvarların arasından esen Maya topraklarının o ilkel, şamanik rüzgarı ve malikaneye çöken o agresif, intikam dolu karanlık zeka, içeri girenleri anında ağır bir melankoliyle vurur.",4"""

# Split by fixing the missing newline before a quote after a number
formatted_data = re.sub(r'(\d)"', r'\1\n"', data)

import io
reader = csv.reader(io.StringIO(formatted_data))
with open('perili_mekanlar.csv', 'a', encoding='utf-8', newline='') as f:
    writer = csv.writer(f)
    for row in reader:
        if len(row) == 5:
            row.append('') # resim_url
        writer.writerow(row)

print("Meksika kayitlari eklendi.")
